+import { createApp } from "../src/http/server.js";
+
+test("keys enforce roles and successful writes are audited", async () => {
+  const { store } = app();
+  const handle = createApp(store, { clock: () => Date.parse("2026-10-28T10:00:00Z") });
+  const request = (key, method, path, body) => handle({ method, path, body, headers: key ? { Authorization: `Bearer ${key}` } : {} });
